/* @lc app=leetcode id=1766 lang=kotlin */ class Solution { fun gcd(a: Int, b: Int): Int = if (b == 0) a else gcd(b, a % b) fun getCoprimes(nums: IntArray, edges: Array<IntArray>): IntArray = nums.size.let { n -> Array(n) { ArrayList<Int>() }.also { g -> edges.forEach { (a, b) -> g[a].add(b).also { g[b].add(a) } } }.let { g -> IntArray(n) { -1 }.let { ans -> IntArray(n).let { dep -> IntArray(n).let { par -> Array(51) { ArrayList<Int>() }.let { stk -> java.util.ArrayDeque<IntArray>().also { it.addFirst(intArrayOf(0, -1, 0)) }.let { st -> (sequenceOf(0) + generateSequence { st.peekFirst()?.let { f -> if (f[2] < g[f[0]].size) g[f[0]][f[2]++].let { v -> if (v == f[1]) -1 else st.addFirst(intArrayOf(v, f[0], 0)).also { par[v] = f[0] }.let { v * 2 } } else st.pollFirst().let { f[0] * 2 + 1 } } }).filter { it >= 0 }.forEach { e -> if (e % 2 == 0) (e / 2).let { v -> (if (v == 0) 0 else dep[par[v]] + 1).also { dep[v] = it }.let { (1..50).filter { c -> gcd(c, nums[v]) == 1 && stk[c].isNotEmpty() }.maxByOrNull { c -> dep[stk[c].last()] }?.let { c -> stk[c].last() } ?: -1 }.also { ans[v] = it }.let { stk[nums[v]].add(v) } } else stk[nums[(e - 1) / 2]].let { it.removeAt(it.size - 1) } } } } } }.let { ans } } } } }